.search-box {
  position: relative;
  display: flex;
  align-items: center;
  height: 46px;
  margin-top: 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  transition: border-color 150ms ease, background 150ms ease;
}
.search-box input {
  min-width: 0;
  flex: 1;
  height: 100%;
  padding: 0 9px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 13.5px;
}
.search-box:focus-within {
  border-color: rgba(239, 217, 176, 0.56);
  background: rgba(239, 217, 176, 0.05);
}

