.rotary-dial { position: relative; width: 88px; height: 88px; border: 1px solid #10120f; border-radius: 50%; background: repeating-conic-gradient(#66675c 0deg 3deg, #30322b 3deg 8deg); box-shadow: 0 4px 3px #11130f, 0 8px 12px rgba(0,0,0,0.35), inset 0 1px 1px #9c9c88; cursor: ns-resize; touch-action: none; user-select: none; }
.dial-face { position: absolute; inset: 5px; border-radius: 50%; background: linear-gradient(135deg, #57594e, #30322b 65%); box-shadow: inset 0 2px 1px #7d7e6f, inset 0 -2px 3px #1a1c17; transform: rotate(var(--dial-angle, -135deg)); pointer-events: none; }
.dial-pointer { position: absolute; top: 6px; left: calc(50% - 2px); width: 4px; height: 13px; border-radius: 2px; background: #ead9b6; }
.tuner-grip { position: absolute; top: 28px; left: 7px; right: 7px; height: 23px; border: 1px solid #24271f; border-radius: 5px; background: linear-gradient(#9b9c88, #535649 45%, #373a30); box-shadow: inset 0 1px 1px #b8b7a1, 0 4px 5px #171a13; }

